package com.helmifr.library.receipt;

import jakarta.persistence.*;
import java.time.Instant;
import lombok.Getter;
import lombok.Setter;

/** A signing key generated by the app when none is configured. */
@Entity
@Getter
@Setter
@Table(name = "receipt_keys")
public class ReceiptKey {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "key_id", nullable = false, length = 40)
    private String keyId;

    /** Base64 X.509. */
    @Column(name = "public_key", nullable = false, length = 500)
    private String publicKey;

    /** Base64 PKCS#8. */
    @Column(name = "private_key", nullable = false, length = 500)
    private String privateKey;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;
}
